differences.test:
import pytest


def test_generated():
    from sympy import symbols
    from sympy.polys.specialpolys import swinnerton_dyer_poly
    x = symbols('x')

    def outcome(f):
        try:
            value = f()
            return type(value).__name__ + ': ' + str(value)
        except Exception as exc:
            return 'raised ' + type(exc).__name__
    assert repr([outcome(lambda: swinnerton_dyer_poly(1, 'x')), outcome(lambda: swinnerton_dyer_poly(1.2, x)), outcome(lambda: swinnerton_dyer_poly(2, x, polys=True))]) == '[\'Add: x**2 - 2\', \'raised ValueError\', "Poly: Poly(x**4 - 10*x**2 + 1, x, domain=\'ZZ\')"]'

